import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { sheetKey } from '../sheet/sheet';

/** A person's plan: a DRAFT claim of `amount` on every plan date, `start` then every `every` days, or for a
 *  monthly plan (`day` set, `every` null) that day of every month from the start, up to `end` (yyyy-MM-dd);
 *  `generated` is how many claims it has made so far; `nextDates` its first five plan dates after the sheet's today and on or before
 *  the end, comma and space separated (none while paused); `paused` whether it is paused now. A plan date on or after
 *  the day it was paused and before the day it was resumed is skipped. */
export type Plan = {
  id: number;
  personId: number;
  amount: string;
  start: string;
  every: number | null;
  day: number | null;
  end: string;
  generated: number;
  nextDates: string;
  paused: boolean;
  /** Its amount changes, oldest first, each `<date> amount=<amount>`. */
  changes: string[];
};

/** Under the sheet's key, so loading the sheet again re-reads its plans. */
export const plansKey = (sheet: string) => [...sheetKey(sheet), 'plans'] as const;

export function usePlans(sheet: string) {
  return useQuery({
    queryKey: plansKey(sheet),
    queryFn: () => getJson<Plan[]>(`/api/sheets/${encodeURIComponent(sheet)}/plans`),
    enabled: sheet !== '',
  });
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { sheetKey } from '../sheet/sheet';

/** A person's opening balance for a period: the period's name, the person's id and the amount (two decimals),
 *  the sum of the amounts pasted for them in it. */
export type Opening = { period: string; personId: number; amount: string };

/** Under the sheet's key, so loading the sheet again re-reads its opening balances. */
export const openingsKey = (sheet: string) => [...sheetKey(sheet), 'openings'] as const;

/** Every opening balance on the sheet. */
export function useOpenings(sheet: string) {
  return useQuery({
    queryKey: openingsKey(sheet),
    queryFn: () => getJson<Opening[]>(`/api/sheets/${encodeURIComponent(sheet)}/openings`),
    enabled: sheet !== '',
  });
}

/** The person's opening balance for the period, 0.00 when none was pasted. */
export function openingOf(openings: Opening[] | undefined, period: string, personId: number): string {
  return (openings ?? []).find((o) => o.period === period && o.personId === personId)?.amount ?? '0.00';
}

